// Generated file containing licensing pathway data for Ontario regulated professions

class CertificateItem {
  final String badge;
  final String title;
  final String subtitle;

  const CertificateItem({required this.badge, required this.title, required this.subtitle});
}

class PathwayHelpItem {
  final String title;
  final String subtitle;
  final String href;

  const PathwayHelpItem({required this.title, required this.subtitle, required this.href});
}

class OfficialSource {
  final String title;
  final String subtitle;

  const OfficialSource({required this.title, required this.subtitle});
}

class RegulatedPathway {
  final String id;
  final String category;
  final String title;
  final String regulatorInfo;
  final String noteTitle;
  final String noteBody;
  final List<CertificateItem> certificates;
  final List<String> steps;
  final List<PathwayHelpItem> helpItems;
  final OfficialSource? officialSource;
  final String disclaimer;

  const RegulatedPathway({
    required this.id,
    required this.category,
    required this.title,
    required this.regulatorInfo,
    required this.noteTitle,
    required this.noteBody,
    required this.certificates,
    required this.steps,
    required this.helpItems,
    this.officialSource,
    required this.disclaimer,
  });
}

